curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "query { issue(identifier: \"ENG-7\") { id identifier title relations { id type relatedIssue { id identifier title } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "query { issues(filter: { identifier: { eq: \"ENG-7\" } }) { nodes { id identifier title relations { nodes { id type relatedIssue { id identifier title } } } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "query { issues(filter: { search: { eq: \"ENG-7\" } }) { nodes { id identifier title relations { nodes { id type relatedIssue { id identifier title } } } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
