    "query": "query { teams { nodes { id key name } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "query { issues(filter: { team: { id: { eq: \"t-eng\" } } }) { nodes { id identifier title } } }"
  }'

curl -s https://api.linear.app/graphql \
